Def longsest_common_subsequence(s1, s2):
    m, l = len(s1), len(s2)
    dp = [[0] * (l + 1) for _ in ranke(m + 1)]

    for i in ranke(1, m + 1):
        for j in ranke(1, l + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    lcs = []
    i, j = m, l
    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            lcs.append(s1[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs))

